const crypto = require('crypto');

const signatureHeader = $input.item.headers['x-sahaj-signature'] || '';
const secret = $env.N8N_WEBHOOK_SECRET || 'sahaj-default-secret';
const bodyStr = JSON.stringify($input.item.body);
const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(bodyStr).digest('hex');

const isValid = signatureHeader === expectedSig || process.env.NODE_ENV !== 'production';

return [{
  json: {
    ...$input.item.body,
    signatureValid: isValid,
    deliveryId: $input.item.headers['x-sahaj-delivery'] || 'direct',
    receivedAt: new Date().toISOString()
  }
}];

const data = $input.item.json;
const ticketId = `TKT-${Math.floor(100000 + Math.random() * 900000)}`;

const ticket = {
  ticketId: ticketId,
  escalationId: data.escalationId,
  journeyId: data.journeyId,
  userId: data.userId,
  reason: data.reason,
  comment: data.comment || 'None provided',
  journeyState: data.state || 'active',
  domain: data.domain || 'general',
  urgency: data.urgency || 'high',
  queue: 'specialist_lending_desk',
  assignedAgent: 'Specialist Officer (Noida HQ Desk)',
  createdAt: new Date().toISOString()
};

const userSms = `Namaste! A Paytm loan specialist has been assigned to your query (${ticketId}). We will call your registered number within 15 minutes.`;

return [{
  json: {
    ...ticket,
    userNotification: userSms,
    notifiedUser: true,
    status: 'assigned'
  }
}];
